            color: var(--text-dark);
            line-height: 1.6;
        }
        header {
            background-color: var(--white);
            box-shadow: var(--shadow);
            position: sticky;
            top: 0;
            z-index: 1000;
        }
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }
        .nav-wrapper {
            display: flex;
            justify-content: space-between;
            align-items: center;
            height: 70px;
        }
        .logo {
            font-size: 24px;
            font-weight: bold;
            color: var(--primary-color);
            text-decoration: none;
            display: flex;
            align-items: center;
        }
        .logo span {
            color: var(--text-dark);
            margin-left: 5px;
        }
        nav ul {
            display: flex;
            list-style: none;
            gap: 30px;
        }
        nav a {
            text-decoration: none;
            color: var(--text-dark);
            font-weight: 500;
            transition: color 0.3s;
        }
        nav a:hover {
            color: var(--primary-color);
        }
        .cart-icon {
            background-color: var(--primary-color);
            color: var(--white);
            padding: 5px 15px;
            border-radius: 20px;
            font-size: 14px;
        }
        .hero {
            background: linear-gradient(135deg, #fff5e6 0%, #ffe4cc 100%);
            padding: 60px 0;
            text-align: center;
        }
        .hero h1 {
            font-size: 36px;
            margin-bottom: 15px;
            color: var(--text-dark);
        }
        .hero p {
            font-size: 18px;
            color: var(--text-light);
            margin-bottom: 30px;
        }
        .search-box {
