        .section-title {
            font-size: 24px;
            margin: 40px 0 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
        .view-all {
            font-size: 14px;
            color: var(--primary-color);
            text-decoration: none;
        }
        .categories {
