            bottom: 10px;
            left: 10px;
            background: rgba(0,0,0,0.7);
            color: var(--white);
            padding: 5px 10px;
            border-radius: 4px;
            font-size: 12px;
        }
        .r-content {
            padding: 15px;
        }
        .r-title {
            font-size: 18px;
            font-weight: bold;
            margin-bottom: 5px;
        }
        .r-tags {
            font-size: 12px;
            color: var(--text-light);
            margin-bottom: 10px;
        }
        .r-rating {
            color: #ff9800;
            font-size: 14px;
            margin-bottom: 10px;
        }
        .r-meta {
            display: flex;
            justify-content: space-between;
            font-size: 13px;
            color: var(--text-light);
            border-top: 1px solid #eee;
            padding-top: 10px;
        }
        footer {
            background: #222;
            color: #ccc;
            padding: 40px 0;
            margin-top: auto;
        }
        .footer-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 30px;
        }
        .footer-col h3 {
            color: var(--white);
            margin-bottom: 20px;
        }
        .footer-col ul {
            list-style: none;
        }
        .footer-col li {
            margin-bottom: 10px;
        }
        .footer-col a {
            color: #ccc;
            text-decoration: none;
        }
